svg.script:
/**/
(function() {
  var root = document.getElementById('a12p1h-svg');
  if (!root) return;

  // Dados Didáticos dos 4 Endereços Pélvicos
  var zoneData = {
    all: {
      badgeText: "4 ENDEREÇOS",
      badgeColor: "var(--a12p1h-card-border, #4a1d43)",
      title: "Análise Topográfica Integrada",
      spaceLines: [
        "Visão sintética da pelve feminina dividida em 4 compartimentos",
        "estratégicos: cada zona possui limites anatômicos rígidos,",
        "vascularização própria e padrão de acometimento patológico."
      ],
      riskLines: [
        "O erro de localização leva a diagnósticos incorretos e iatrogenia.",
        "A proximidade entre útero, ureter, reto e assoalho exige",
        "reconhecimento topográfico imediato antes da intervenção."
      ],
      ruleTitle: "Diretriz Geral da Residência:",
      ruleLines: [
        "Associe sempre o sintoma ao compartimento anatômico",
        "antes de indicar a via de abordagem ou ligadura vascular."
      ],
      ruleColor: "var(--a12p1h-yellow, #eab308)",
      table: [
        { name: "Débito sang. placentário", val: "500-700 mL/min", status: "critical" },
        { name: "Distância Ureter-Artéria", val: "1.5 - 2.0 cm", status: "alert" },
        { name: "Espessamento Septal", val: "> 5 mm (Foco profundo)", status: "critical" },
        { name: "Mobilidade Uretral / POP-Q", val: "Ângulo > 30° / Est. II+", status: "normal" }
      ]
    },
    zone1: {
      badgeText: "ENDEREÇO 1",
      badgeColor: "var(--a12p1h-z1-color, #ef4444)",
      title: "Hemorragia Pós-Parto (HPP)",
      spaceLines: [
        "Segmento inferior e corpo uterino (miométrio intramural).",
        "Sítio de inserção placentária e irrigação primária via ramos",
        "ascendentes e helicinais da Artéria Uterina."
      ],
      riskLines: [
        "Atonia uterina impede o grampeamento fisiológico (ligaduras de",
        "Pinard). Débito vascular massivo (até 700 mL/min) conduz rápido",
        "ao choque hipovolêmico e Coagulação Intravascular Disseminada."
      ],
      ruleTitle: "Regra de Ouro (HPP):",
      ruleLines: [
        "Inicie ocitócicos e compressão bimanual (Hamilton). Na falha,",
        "aplique balão de Bakri ou sutura de B-Lynch antes da histerectomia."
      ],
      ruleColor: "var(--a12p1h-z1-color, #ef4444)",
      table: [
        { name: "Débito Sangue Placentário", val: "600-700 mL/min", status: "critical" },
        { name: "Perda volêmica tolerada", val: "< 500 mL (Vaginal)", status: "normal" },
        { name: "Tempo limite balão Bakri", val: "24 horas máximo", status: "alert" },
        { name: "Pressão de insuflação Bakri", val: "300 - 500 mL SF", status: "normal" }
      ]
    },
    zone2: {
      badgeText: "ENDEREÇO 2",
      badgeColor: "var(--a12p1h-z2-color, #f97316)",
      title: "Cirurgia Ginecológica & Sangramento",
      spaceLines: [
        "Paramétrio e ligamento largo (base do ligamento cardinal).",
        "Zona de cruzamento crítico onde a Artéria Uterina cruza",
        "SUPERIORMENTE ao Ureter ('Water under the bridge')."
      ],
      riskLines: [
        "Risco de ligadura inadvertida ou transecção do ureter a 1,5 - 2 cm",
        "lateral ao colo uterino durante o pinçamento do pedículo uterino",
        "em histerectomias abdominais ou vaginais."
      ],
      ruleTitle: "Regra de Ouro (Cirúrgica):",
      ruleLines: [
        "Identifique e rebata visivelmente a lâmina ureteral antes de",
        "qualquer pinçamento ou cauterização no espaço retroperitoneal."
      ],
      ruleColor: "var(--a12p1h-z2-color, #f97316)",
      table: [
        { name: "Cruzamento Ureter-Artéria", val: "1.5 - 2.0 cm do colo", status: "alert" },
        { name: "Incidência lesão ureteral", val: "0.5% - 1.5% histerectomias", status: "critical" },
        { name: "Débito Ureteral Normal", val: "0.5 - 1.0 mL/kg/h", status: "normal" },
        { name: "Distância limite de cautério", val: "> 10 mm do ureter", status: "alert" }
      ]
    },
    zone3: {
      badgeText: "ENDEREÇO 3",
      badgeColor: "var(--a12p1h-z3-color, #d946ef)",
      title: "Endometriose Profunda",
      spaceLines: [
        "Compartimento posterior: fundo de saco de Douglas,",
        "ligamentos uterossacros, septo retovaginal e alça retossigmoide.",
        "Zona de infiltração subperitoneal profunda (> 5 mm)."
      ],
      riskLines: [
        "Fibrose densa com obliteração do fundo de saco, encarceramento",
        "do ureter distal e comprometimento do plexo hipogástrico inferior",
        "(causando dor pélvica crônica, dispareunia e disquezia)."
      ],
      ruleTitle: "Regra de Ouro (Endometriose):",
      ruleLines: [
        "O mapeamento pré-operatório por ultrassom com preparo intestinal",
        "é obrigatório para planejar ressecção discoide ou shaving seguro."
      ],
      ruleColor: "var(--a12p1h-z3-color, #d946ef)",
      table: [
        { name: "Profundidade de Infiltração", val: "> 5.0 mm (Critério)", status: "critical" },
        { name: "Acometimento Uterossacro", val: "Presente em 60-70%", status: "alert" },
        { name: "Margem de Segurança Ner.", val: "> 3 mm do PLEXO", status: "normal" },
        { name: "Estadiamento ASRM", val: "Grau IV (Severo)", status: "critical" }
      ]
    },
    zone4: {
      badgeText: "ENDEREÇO 4",
      badgeColor: "var(--a12p1h-z4-color, #06b6d4)",
      title: "Incontinência & Prolapso Pélvico",
      spaceLines: [
        "Compartimento anterior e apical: fáscia endopélvica (arco tendíneo),",
        "placa do músculo levantador do ânus (puborretal/pubocóccigeo)",
        "e suporte de DeLancey (Nível I e Nível II)."
      ],
      riskLines: [
        "Rotura ou avulsão fascial leva à cistocele (defeito central vs lateral)",
        "e hipermotilidade do colo vesical, resultando em Incontinência",
        "Urinária de Esforço (IUE) ou prolapso de cúpula."
      ],
      ruleTitle: "Regra de Ouro (Uroginecologia):",
      ruleLines: [
        "Diferencie hipermotilidade uretral de deficiência esfincteriana",
        "pelo Teste do Cotonete (Q-tip > 30°) e Estudo Urodinâmico (VLPP)."
      ],
      ruleColor: "var(--a12p1h-z4-color, #06b6d4)",
      table: [
        { name: "Teste do Q-Tip (Mobilidade)", val: "> 30° (Hipermotilidade)", status: "alert" },
        { name: "Pressão Perda Esfincteriana", val: "< 60 cmH2O (Defic. Esf.)", status: "critical" },
        { name: "Força Assoalho (Oxford)", val: "Grau 4-5 (Preservado)", status: "normal" },
        { name: "Estadiamento POP-Q", val: "Ponto Aa/Ba (+1 a +3)", status: "alert" }
      ]
    }
  };

  // Atualiza os Textos do Painel Dinamicamente
  function updatePanel(zoneId) {
    var data = zoneData[zoneId] || zoneData.all;

    // Badge e Título
    var badgeBg = document.getElementById('a12p1h-badge-bg');
    var badgeTxt = document.getElementById('a12p1h-badge-txt');
    var pTitle = document.getElementById('a12p1h-p-title');

    if (badgeBg) badgeBg.setAttribute('fill', data.badgeColor);
    if (badgeTxt) badgeTxt.textContent = data.badgeText;
    if (pTitle) pTitle.textContent = data.title;

    // Texto do Espaço
    var txtSpace = document.getElementById('a12p1h-txt-space');
    if (txtSpace) {
      txtSpace.innerHTML = '';
      data.spaceLines.forEach(function(line, idx) {
        var tspan = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
        tspan.setAttribute('x', '0');
        tspan.setAttribute('dy', idx === 0 ? '0' : '16');
        tspan.textContent = line;
        txtSpace.appendChild(tspan);
      });
    }

    // Texto do Risco
    var txtRisk = document.getElementById('a12p1h-txt-risk');
    if (txtRisk) {
      txtRisk.innerHTML = '';
      data.riskLines.forEach(function(line, idx) {
        var tspan = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
        tspan.setAttribute('x', '0');
        tspan.setAttribute('dy', idx === 0 ? '0' : '16');
        tspan.textContent = line;
        txtRisk.appendChild(tspan);
      });
    }

    // Regra de Conduta
    var alertBg = document.getElementById('a12p1h-alert-bg');
    var txtRule = document.getElementById('a12p1h-txt-rule');
    if (alertBg) alertBg.setAttribute('stroke', data.ruleColor);
    if (txtRule) {
      txtRule.innerHTML = '';

      var tspanTitle = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
      tspanTitle.setAttribute('x', '12');
      tspanTitle.setAttribute('dy', '0');
      tspanTitle.setAttribute('class', 'a12p1h-bold-txt');
      tspanTitle.setAttribute('fill', data.ruleColor);
      tspanTitle.textContent = data.ruleTitle;
      txtRule.appendChild(tspanTitle);

      data.ruleLines.forEach(function(line) {
        var tspan = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
        tspan.setAttribute('x', '12');
        tspan.setAttribute('dy', '18');
        tspan.textContent = line;
        txtRule.appendChild(tspan);
      });
    }

    // Tabela Dinâmica
    data.table.forEach(function(row, idx) {
      var num = idx + 1;
      var nameEl = document.getElementById('a12p1h-row' + num + '-name');
      var valEl = document.getElementById('a12p1h-row' + num + '-val');
      var dotEl = document.getElementById('a12p1h-row' + num + '-dot');

      if (nameEl) nameEl.textContent = row.name;
      if (valEl) valEl.textContent = row.val;
      if (dotEl) {
        dotEl.setAttribute('class', 'a12p1h-dot-' + row.status);
      }
    });
  }

  // Função de Troca de Estado Ativo
  function setActiveZone(zoneId) {
    root.setAttribute('data-a12p1h-active', zoneId);
    updatePanel(zoneId);
  }

  // Atribuição de Eventos de Clique e Teclado
  function bindZoneEvents(selector, zoneId) {
    var elements = root.querySelectorAll(selector);
    elements.forEach(function(el) {
      el.addEventListener('click', function(e) {
        e.stopPropagation();
        setActiveZone(zoneId);
      });

      el.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          setActiveZone(zoneId);
        }
      });
    });
  }

  // Vincular Hotspots, Shapes e Rótulos Externos
  bindZoneEvents('.a12p1h-z1-grp', 'zone1');
  bindZoneEvents('.a12p1h-z2-grp', 'zone2');
  bindZoneEvents('.a12p1h-z3-grp', 'zone3');
  bindZoneEvents('.a12p1h-z4-grp', 'zone4');

  // Vincular Botões de Filtro
  var btnAll = document.getElementById('a12p1h-btn-all');
  var btnZ1 = document.getElementById('a12p1h-btn-z1');
  var btnZ2 = document.getElementById('a12p1h-btn-z2');
  var btnZ3 = document.getElementById('a12p1h-btn-z3');
  var btnZ4 = document.getElementById('a12p1h-btn-z4');

  if (btnAll) btnAll.addEventListener('click', function() { setActiveZone('all'); });
  if (btnZ1) btnZ1.addEventListener('click', function() { setActiveZone('zone1'); });
  if (btnZ2) btnZ2.addEventListener('click', function() { setActiveZone('zone2'); });
  if (btnZ3) btnZ3.addEventListener('click', function() { setActiveZone('zone3'); });
  if (btnZ4) btnZ4.addEventListener('click', function() { setActiveZone('zone4'); });

  // Suporte a Teclado nos Botões
  [btnAll, btnZ1, btnZ2, btnZ3, btnZ4].forEach(function(btn) {
    if (!btn) return;
    btn.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        btn.click();
      }
    });
  });

  // Inicialização
  updatePanel('all');
})();
/**/
